import React, {
  useState
} from "react";
import { useNavigate } from "react-router-dom";

function Login() {
  const navigate = useNavigate();

  const [username, setUsername] =
    useState("");

  const [password, setPassword] =
    useState("");

  const [otp, setOtp] =
    useState("");

  const [mfaRequired, setMfaRequired] =
    useState(false);

  const [error, setError] =
    useState("");

  const handleLogin = async () => {
    try {
      const response = await fetch(
        "http://127.0.0.1:8000/auth/login",
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json"
          },
          body: JSON.stringify({
            username,
            password
          })
        }
      );

      const data =
        await response.json();

      if (data.mfa_required) {
        setMfaRequired(true);

        alert(
          "OTP: " + data.otp
        );

        return;
      }

      if (data.access_token) {
        localStorage.setItem(
          "access_token",
          data.access_token
        );

        navigate("/");
      }
    } catch (err) {
      setError(
        "Login failed"
      );
    }
  };

  const verifyOTP = async () => {
    try {
      const response = await fetch(
        "http://127.0.0.1:8000/auth/verify-otp",
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json"
          },
          body: JSON.stringify({
            username,
            otp
          })
        }
      );

      const data =
        await response.json();

      if (data.access_token) {
        localStorage.setItem(
          "access_token",
          data.access_token
        );

        navigate("/");
      }
    } catch (err) {
      setError(
        "OTP verification failed"
      );
    }
  };

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <h1>Cyber Threat Login</h1>

        {error && (
          <p style={styles.error}>
            {error}
          </p>
        )}

        {!mfaRequired ? (
          <>
            <input
              style={styles.input}
              placeholder="Username"
              value={username}
              onChange={(e) =>
                setUsername(
                  e.target.value
                )
              }
            />

            <input
              style={styles.input}
              type="password"
              placeholder="Password"
              value={password}
              onChange={(e) =>
                setPassword(
                  e.target.value
                )
              }
            />

            <button
              style={styles.button}
              onClick={
                handleLogin
              }
            >
              Login
            </button>
          </>
        ) : (
          <>
            <input
              style={styles.input}
              placeholder="Enter OTP"
              value={otp}
              onChange={(e) =>
                setOtp(
                  e.target.value
                )
              }
            />

            <button
              style={styles.button}
              onClick={
                verifyOTP
              }
            >
              Verify OTP
            </button>
          </>
        )}
      </div>
    </div>
  );
}

const styles = {
  container: {
    display: "flex",
    justifyContent:
      "center",
    alignItems:
      "center",
    minHeight:
      "100vh",
    background:
      "#0f172a",
    color: "white"
  },

  card: {
    background:
      "#1e293b",
    padding: "40px",
    borderRadius:
      "12px",
    width: "350px"
  },

  input: {
    width: "100%",
    padding: "12px",
    marginTop: "15px"
  },

  button: {
    width: "100%",
    padding: "12px",
    marginTop: "20px",
    background:
      "#00ff99"
  },

  error: {
    color: "red"
  }
};

export default Login;
